using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.AccessControl;

public sealed class AccessGrant : Aggregate
{
    readonly Uuid _tenantId;
    AccessGrantTerms? _terms;
    Uuid? _membershipEpisodeId;
    bool _isRevoked;
    Uuid _issuedEventId;

    public bool IsRevoked => _isRevoked;
    public Uuid? MembershipEpisodeId => _membershipEpisodeId;

    public AccessGrant(Uuid tenantId, Uuid grantId)
        : base(grantId, new EventStreamAddress(tenantId.ToString(), "access-grants", grantId.ToString()))
    {
        _tenantId = tenantId;
        On<AccessGrantIssued>(ev =>
        {
            _terms = ev.Terms;
            _membershipEpisodeId = ev.MembershipEpisodeId;
            _issuedEventId = ev.Metadata.EventId;
        });
        On<AccessGrantRevoked>(_ => _isRevoked = true);
    }

    public Result Issue(AccessGrantTerms terms, Uuid? membershipEpisodeId = null)
    {
        var validation = Validate(terms);
        if (validation is not null)
            return Result.Failure(validation);

        if (_terms is not null)
            return _isRevoked
                ? Result.Failure(new RequestError(RequestErrorKind.Conflict,
                    "A revoked access grant cannot be reissued."))
                : _terms == terms && _membershipEpisodeId == membershipEpisodeId
                ? Result.Success
                : Result.Failure(new RequestError(RequestErrorKind.Conflict,
                    "The access grant already has different terms."));

        RaiseEvent(new AccessGrantIssued(_tenantId, Id, terms, membershipEpisodeId));
        return Result.Success;
    }

    public Result Revoke(ActorReference revokedBy, DateTimeOffset revokedAt)
    {
        if (_terms is null)
            return Result.Failure(new RequestError(RequestErrorKind.NotFound, "The access grant was not found."));
        if (_isRevoked)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict, "The access grant is already revoked."));
        if (!IsValidActor(revokedBy) || revokedAt == default)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A grant revocation requires an actor and timestamp."));

        RaiseEvent(new AccessGrantRevoked(_tenantId, Id, revokedBy, revokedAt));
        return Result.Success;
    }

    internal Result RevokeForRetirement(MembershipTerminationProof proof, Uuid issuedEventId,
        DateTimeOffset revokedAt)
    {
        if (proof.TenantId != _tenantId || proof.MembershipEpisodeId == Uuid.Empty || proof.EventId == Uuid.Empty ||
            issuedEventId == Uuid.Empty)
            return Result.Failure(new RequestError(RequestErrorKind.Validation, "Exact retirement and grant proofs are required."));
        if (_terms is null)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "The proven grant is not available yet.", isTransient: true));
        if (_isRevoked || _issuedEventId != issuedEventId || _membershipEpisodeId != proof.MembershipEpisodeId ||
            _terms.Principal.Kind != AccessGrantPrincipalKind.Member || _terms.Principal.Id != proof.MemberId)
            return Result.Success;
        return Revoke(ActorReference.ForMember(proof.ActorMemberId, proof.ActorDisplay), revokedAt);
    }

    RequestError? Validate(AccessGrantTerms terms)
    {
        if (terms is null || terms.Principal is null || terms.Scope is null || terms.Source is null)
            return new RequestError(RequestErrorKind.Validation, "An access grant requires complete terms.");
        if (terms.Principal.Id == Uuid.Empty || !Enum.IsDefined(terms.Principal.Kind) ||
            terms.RoleId == Uuid.Empty || terms.Scope.Id == Uuid.Empty ||
            !Enum.IsDefined(terms.Scope.Kind) || !IsValidActor(terms.GrantedBy) ||
            string.IsNullOrWhiteSpace(terms.Source.Kind) || string.IsNullOrWhiteSpace(terms.Source.Id) ||
            terms.EffectiveFrom == default ||
            terms.EffectiveUntil is { } until && until <= terms.EffectiveFrom)
            return new RequestError(RequestErrorKind.Validation, "The access grant terms are invalid.");
        if (terms.Scope.Kind == AccessGrantScopeKind.Organization && terms.Scope.Id != _tenantId)
            return new RequestError(RequestErrorKind.Validation, "An organization scope requires an organization id.");
        if (terms.Scope.Kind == AccessGrantScopeKind.SharedResource &&
            string.IsNullOrWhiteSpace(terms.Scope.ResourceType))
            return new RequestError(RequestErrorKind.Validation,
                "A shared resource scope requires its resource type.");
        if (terms.Scope.Kind != AccessGrantScopeKind.SharedResource && terms.Scope.ResourceType is not null)
            return new RequestError(RequestErrorKind.Validation,
                "Only a shared resource scope may specify a resource type.");
        return null;
    }

    static bool IsValidActor(ActorReference? actor) =>
        actor is { Kind: "member" } &&
        !string.IsNullOrWhiteSpace(actor.Id) && !string.IsNullOrWhiteSpace(actor.Display);
}

using Cntryl.Portia;
using System.Security.Cryptography;
using System.Text.Json;

namespace Bdgrz.Compliance.Features.AccessControl;

public sealed class Member : Aggregate
{
    readonly Uuid _tenantId;
    readonly Uuid _selectedEpisodeId;
    Uuid _userId;
    bool _isRegistered;
    string? _affiliation;
    DateOnly? _membershipExpiresOn;
    Uuid _membershipEpisodeId;
    bool _isSuspended;
    bool _isDeprovisioned;
    bool _isDeprovisionCleanupComplete;
    Uuid _deprovisionedByMemberId;
    string? _deprovisionedByDisplay;
    DateTimeOffset? _deprovisionedAt;
    string? _deprovisionReason;
    MemberDeprovisioned? _currentTermination;
    MemberDeprovisioned? _selectedTermination;
    bool _selectedCleanupCompleted;

    public bool IsRegistered => _isRegistered;
    public string? Affiliation => _affiliation;
    public DateOnly? MembershipExpiresOn => _membershipExpiresOn;
    public Uuid UserId => _userId;
    public Uuid MembershipEpisodeId => _membershipEpisodeId;
    public bool IsSuspended => _isSuspended;
    public bool IsDeprovisioned => _isDeprovisioned;
    public bool IsDeprovisionCleanupComplete => _isDeprovisionCleanupComplete;
    public Uuid DeprovisionedByMemberId => _deprovisionedByMemberId;
    public string? DeprovisionedByDisplay => _deprovisionedByDisplay;
    public DateTimeOffset? DeprovisionedAt => _deprovisionedAt;
    public string? DeprovisionReason => _deprovisionReason;
    public bool SelectedCleanupCompleted => _selectedCleanupCompleted;
    public MembershipTerminationProof? TerminationProof => _selectedTermination is { } fact
        ? new MembershipTerminationProof(_tenantId, Id, fact.UserId, fact.MembershipEpisodeId,
            fact.Metadata.EventId, fact.Metadata.AggregateVersion, fact.Metadata.AggregateVersion - 1,
            Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(fact,
                ComplianceCoreJsonContext.Default.MemberDeprovisioned))),
            fact.DeprovisionedByMemberId, fact.DeprovisionedByDisplay)
        : null;

    public bool IsAccessEligibleOn(DateOnly utcDate) => IsRegistered && !_isSuspended &&
        !_isDeprovisioned && (_membershipExpiresOn is not { } expiresOn || utcDate <= expiresOn);

    public Member(Uuid tenantId, Uuid userId, Uuid selectedEpisodeId = default)
        : this(tenantId, RbacIds.Member(tenantId, userId), userId, selectedEpisodeId)
    {
    }

    /// <summary>
    ///     Opens a member stream by member identity for read-only verification, such as checking
    ///     that a responsibility holder is still active. Commands require the user constructor.
    /// </summary>
    public static Member ForVerification(Uuid tenantId, Uuid memberId, Uuid selectedEpisodeId = default) =>
        new(tenantId, memberId, Uuid.Empty, selectedEpisodeId);

    Member(Uuid tenantId, Uuid memberId, Uuid userId, Uuid selectedEpisodeId)
        : base(memberId,
            new EventStreamAddress(tenantId.ToString(), "rbac-members", memberId.ToString()))
    {
        _tenantId = tenantId;
        _selectedEpisodeId = selectedEpisodeId;
        _userId = userId;
        On<MemberRegistered>(registered =>
        {
            var hasFiniteExpiry = registered.MembershipExpiresOn is { } expiresOn &&
                                  expiresOn != DateOnly.MinValue && expiresOn != DateOnly.MaxValue;
            if (registered.Affiliation is not ("client_personnel" or "firm_staff" or "guest") ||
                registered.Affiliation == "guest" && !hasFiniteExpiry ||
                registered.Affiliation != "guest" && registered.MembershipExpiresOn is not null)
                throw new InvalidOperationException("The member registration event has invalid affiliation or expiry terms.");
            _isRegistered = true;
            _affiliation = registered.Affiliation;
            _membershipExpiresOn = registered.MembershipExpiresOn;
            _userId = registered.UserId;
            _membershipEpisodeId = registered.MembershipEpisodeId;
            _isSuspended = false;
            _isDeprovisioned = false;
            _isDeprovisionCleanupComplete = false;
            _currentTermination = null;
            if (_selectedEpisodeId == Uuid.Empty)
            {
                _selectedTermination = null;
                _selectedCleanupCompleted = false;
            }
        });
        On<MemberSuspended>(_ => _isSuspended = true);
        On<MemberReinstated>(_ => _isSuspended = false);
        On<MemberDeprovisioned>(deprovisioned =>
        {
            if (deprovisioned.TenantId != _tenantId || deprovisioned.MemberId != Id ||
                RbacIds.Member(_tenantId, deprovisioned.UserId) != Id ||
                deprovisioned.DeprovisionedByMemberId == Uuid.Empty ||
                string.IsNullOrWhiteSpace(deprovisioned.DeprovisionedByDisplay) ||
                string.IsNullOrWhiteSpace(deprovisioned.Reason) || deprovisioned.DeprovisionedAt == default ||
                deprovisioned.UserId != _userId || !_isRegistered ||
                deprovisioned.MembershipEpisodeId == Uuid.Empty ||
                deprovisioned.MembershipEpisodeId != _membershipEpisodeId)
                throw new InvalidOperationException("Membership retirement must identify its exact registered episode.");
            _isRegistered = false;
            _isSuspended = false;
            _isDeprovisioned = true;
            _isDeprovisionCleanupComplete = false;
            _deprovisionedByMemberId = deprovisioned.DeprovisionedByMemberId;
            _deprovisionedByDisplay = deprovisioned.DeprovisionedByDisplay;
            _deprovisionedAt = deprovisioned.DeprovisionedAt;
            _deprovisionReason = deprovisioned.Reason;
            _currentTermination = deprovisioned;
            if (_selectedEpisodeId == Uuid.Empty || _selectedEpisodeId == deprovisioned.MembershipEpisodeId)
                _selectedTermination = deprovisioned;
        });
        On<MemberDeprovisionCleanupCompleted>(completed =>
        {
            if (completed.TenantId != _tenantId || completed.MemberId != Id || !_isDeprovisioned ||
                _isDeprovisionCleanupComplete || completed.CompletedAt == default ||
                completed.MembershipEpisodeId != _membershipEpisodeId || _currentTermination is null ||
                completed.TerminationEventId != _currentTermination.Metadata.EventId ||
                completed.CommandId != MemberRetirementEffects.CompletionId(completed.TerminationEventId,
                    Id, completed.MembershipEpisodeId))
                throw new InvalidOperationException("Cleanup completion must prove the exact membership retirement.");
            _isDeprovisionCleanupComplete = true;
            if (_selectedTermination?.Metadata.EventId == completed.TerminationEventId)
                _selectedCleanupCompleted = true;
        });
    }

    public Result Register(string affiliation = "client_personnel",
        DateOnly? membershipExpiresOn = null)
    {
        EnsureUserIdentity();
        if (affiliation is not ("client_personnel" or "firm_staff" or "guest"))
            return Result.Failure(new RequestError(RequestErrorKind.Validation, "Invalid membership affiliation."));
        var hasFiniteExpiry = membershipExpiresOn is { } endDate &&
                              endDate != DateOnly.MinValue && endDate != DateOnly.MaxValue;
        if (affiliation == "guest" && !hasFiniteExpiry ||
            affiliation != "guest" && membershipExpiresOn is not null)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "Guest membership requires a finite end date; other affiliations cannot have one."));
        if (_isDeprovisioned && !_isDeprovisionCleanupComplete)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "Membership authority cleanup must finish before a new invitation can take effect."));
        if (!_isRegistered)
            RaiseEvent(new MemberRegistered(_tenantId, Id, _userId, affiliation,
                Uuid.CreateVersion4(), membershipExpiresOn));
        else if (_affiliation != affiliation || _membershipExpiresOn != membershipExpiresOn)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "This membership has different affiliation or expiry terms."));
        return Result.Success;
    }

    public Result Suspend(Uuid actorMemberId, string actorDisplay, DateTimeOffset suspendedAt,
        string reason)
    {
        EnsureUserIdentity();
        if (!_isRegistered)
            return Result.Failure(new RequestError(RequestErrorKind.NotFound,
                "The tenant member was not found."));
        if (_isSuspended)
            return Result.Success;
        if (actorMemberId == Uuid.Empty || string.IsNullOrWhiteSpace(actorDisplay))
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A member identity is required for the suspension history."));
        if (string.IsNullOrWhiteSpace(reason) || reason.Trim().Length > 1000)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "Enter a suspension reason of at most 1000 characters."));

        RaiseEvent(new MemberSuspended(_tenantId, Id, _userId, actorMemberId,
            actorDisplay.Trim(), suspendedAt, reason.Trim()));
        return Result.Success;
    }

    public Result Reinstate(Uuid actorMemberId, string actorDisplay, DateTimeOffset reinstatedAt)
    {
        EnsureUserIdentity();
        if (!_isRegistered)
            return Result.Failure(new RequestError(RequestErrorKind.NotFound,
                "The tenant member was not found."));
        if (!_isSuspended)
            return Result.Success;
        if (actorMemberId == Uuid.Empty || string.IsNullOrWhiteSpace(actorDisplay))
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A member identity is required for the reinstatement history."));

        RaiseEvent(new MemberReinstated(_tenantId, Id, _userId, _affiliation!, actorMemberId,
            actorDisplay.Trim(), reinstatedAt));
        return Result.Success;
    }

    public Result Deprovision(Uuid actorMemberId, string actorDisplay, DateTimeOffset deprovisionedAt,
        string reason)
    {
        EnsureUserIdentity();
        if (_isDeprovisioned)
            return Result.Success;
        if (!_isRegistered)
            return Result.Failure(new RequestError(RequestErrorKind.NotFound,
                "The tenant member was not found."));
        if (actorMemberId == Uuid.Empty || string.IsNullOrWhiteSpace(actorDisplay))
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A member identity is required for the deprovision history."));
        if (deprovisionedAt == default)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A deprovision timestamp is required."));
        if (string.IsNullOrWhiteSpace(reason) || reason.Trim().Length > 1000)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "Enter a deprovision reason of at most 1000 characters."));

        if (_membershipEpisodeId == Uuid.Empty)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "Membership retirement requires its registered episode."));
        RaiseEvent(new MemberDeprovisioned(_tenantId, Id, _userId, actorMemberId,
            actorDisplay.Trim(), deprovisionedAt, reason.Trim(), _membershipEpisodeId));
        return Result.Success;
    }

    public Result CompleteDeprovisionCleanup(MembershipTerminationProof proof, Uuid commandId,
        DateTimeOffset completedAt)
    {
        EnsureUserIdentity();
        if (proof is null || proof != TerminationProof || commandId != MemberRetirementEffects.CompletionId(proof.EventId,
                Id, proof.MembershipEpisodeId))
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "Cleanup requires the exact original termination proof and operation."));
        if (_selectedCleanupCompleted)
            return Result.Success;
        if (!_isDeprovisioned || _membershipEpisodeId != proof.MembershipEpisodeId ||
            _currentTermination?.Metadata.EventId != proof.EventId)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "Membership authority cleanup requires a deprovisioned member."));
        if (_isDeprovisionCleanupComplete)
            return Result.Success;
        if (completedAt == default)
            return Result.Failure(new RequestError(RequestErrorKind.Validation,
                "A cleanup completion timestamp is required."));

        RaiseEvent(new MemberDeprovisionCleanupCompleted(_tenantId, Id, proof.MembershipEpisodeId,
            proof.EventId, commandId, completedAt));
        return Result.Success;
    }

    void EnsureUserIdentity()
    {
        if (_userId == Uuid.Empty)
            throw new InvalidOperationException(
                "A member opened for verification cannot record membership changes.");
    }
}

using System.Diagnostics.CodeAnalysis;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.AccessControl;

[SuppressMessage("Naming", "CA1711:Identifiers should not have incorrect suffix",
    Justification = "RolePermission is the canonical RBAC relationship term.")]
public sealed class RolePermission : Aggregate
{
    readonly Uuid _tenantId;
    readonly Uuid _roleId;
    readonly string _permission;
    readonly Uuid _selectedCommandId;
    DomainEvent? _selectedFact;
    Uuid? _assignmentId;

    public bool IsAssigned => _assignmentId is not null;
    public Uuid? AssignmentId => _assignmentId;
    public Uuid TenantId => _tenantId;
    public Uuid RoleId => _roleId;
    public string Permission => _permission;

    public RolePermission(Uuid tenantId, Uuid roleId, string permission, Uuid selectedCommandId = default)
        : base(RbacIds.RolePermission(tenantId, roleId, Permissions.Normalize(permission)),
            new EventStreamAddress(tenantId.ToString(), "rbac-role-permissions",
                RbacIds.RolePermission(tenantId, roleId, Permissions.Normalize(permission)).ToString()))
    {
        _tenantId = tenantId;
        _roleId = roleId;
        _permission = Permissions.Normalize(permission);
        _selectedCommandId = selectedCommandId;
        On<RolePermissionAssigned>(Apply);
        On<RolePermissionRemoved>(Apply);
    }

    public Result Assign(Uuid commandId, ulong expectedRevision, ActorAttribution actor)
    {
        if (Validate(commandId, actor) is { } error)
            return Result.Failure(error);
        if (_selectedFact is { } prior)
            return prior is RolePermissionAssigned assigned && assigned.ExpectedRevision == expectedRevision &&
                assigned.Actor == actor ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || IsAssigned)
            return Conflict("The role permission changed or is already assigned.");
        RaiseEvent(new RolePermissionAssigned(_tenantId, _roleId, _permission, commandId, expectedRevision, actor));
        return Result.Success;
    }

    public Result Remove(Uuid commandId, ulong expectedRevision, Uuid assignmentId, ActorAttribution actor)
    {
        if (Validate(commandId, actor) is { } error)
            return Result.Failure(error);
        if (assignmentId == Uuid.Empty)
            return Result.Failure(new RequestError(RequestErrorKind.Validation, "An assignment identity is required."));
        if (_selectedFact is { } prior)
            return prior is RolePermissionRemoved removed && removed.ExpectedRevision == expectedRevision &&
                removed.AssignmentId == assignmentId && removed.Actor == actor ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || _assignmentId != assignmentId)
            return Conflict("The role permission revision or assignment episode changed.");
        RaiseEvent(new RolePermissionRemoved(_tenantId, _roleId, _permission, commandId, expectedRevision, actor,
            assignmentId));
        return Result.Success;
    }

    RequestError? Validate(Uuid commandId, ActorAttribution actor) =>
        commandId == Uuid.Empty || commandId != _selectedCommandId || actor is null ||
        string.IsNullOrWhiteSpace(actor.Subject) || string.IsNullOrWhiteSpace(actor.Issuer)
            ? new RequestError(RequestErrorKind.Validation, "A selected command identity and original actor are required.")
            : null;

    void Apply(RolePermissionAssigned ev)
    {
        ValidateFact(ev.TenantId, ev.RoleId, ev.Permission, ev.CommandId, ev.ExpectedRevision, ev.Actor, ev);
        if (IsAssigned)
            throw new InvalidOperationException("An active role permission cannot be assigned again.");
        _assignmentId = ev.CommandId;
    }

    void Apply(RolePermissionRemoved ev)
    {
        ValidateFact(ev.TenantId, ev.RoleId, ev.Permission, ev.CommandId, ev.ExpectedRevision, ev.Actor, ev);
        if (_assignmentId != ev.AssignmentId || ev.AssignmentId == Uuid.Empty)
            throw new InvalidOperationException("Permission removal must close the exact active assignment.");
        _assignmentId = null;
    }

    void ValidateFact(Uuid tenantId, Uuid roleId, string permission, Uuid commandId, ulong expectedRevision,
        ActorAttribution actor, DomainEvent fact)
    {
        if (tenantId != _tenantId || roleId != _roleId || permission != _permission || commandId == Uuid.Empty ||
            expectedRevision != Version || actor is null || string.IsNullOrWhiteSpace(actor.Subject) ||
            string.IsNullOrWhiteSpace(actor.Issuer))
            throw new InvalidOperationException("A permission fact must match its owner, actor and original revision.");
        if (commandId != _selectedCommandId)
            return;
        if (_selectedFact is not null)
            throw new InvalidOperationException("One permission operation cannot be accepted more than once.");
        _selectedFact = fact;
    }

    static Result ChangedIntent() => Conflict("This permission command identity already has different accepted intent.");
    static Result Conflict(string message) => Result.Failure(new RequestError(RequestErrorKind.Conflict, message));
}

using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.AccessControl;

public sealed class TeamMember : Aggregate
{
    readonly Uuid _tenantId;
    readonly Uuid _teamId;
    readonly Uuid _memberId;
    bool _isAssigned;
    Uuid _membershipEpisodeId;
    Uuid _assignmentEventId;
    ulong _assignmentPosition;

    public bool IsAssigned => _isAssigned;
    public Uuid MembershipEpisodeId => _membershipEpisodeId;
    public Uuid AssignmentEventId => _assignmentEventId;
    public ulong AssignmentPosition => _assignmentPosition;

    public TeamMember(Uuid tenantId, Uuid teamId, Uuid memberId)
        : base(
            RbacIds.TeamMember(tenantId, teamId, memberId),
            new EventStreamAddress(
                tenantId.ToString(),
                "rbac-team-members",
                RbacIds.TeamMember(tenantId, teamId, memberId).ToString()))
    {
        _tenantId = tenantId;
        _teamId = teamId;
        _memberId = memberId;
        On<TeamMemberAssigned>(assigned =>
        {
            if (_isAssigned || assigned.TenantId != _tenantId || assigned.TeamId != _teamId ||
                assigned.MemberId != _memberId)
                throw new InvalidOperationException("Assignment requires its exact owner and an empty active slot.");
            _isAssigned = true;
            _membershipEpisodeId = assigned.MembershipEpisodeId;
            _assignmentEventId = assigned.Metadata.EventId;
            _assignmentPosition = assigned.Metadata.AggregateVersion - 1;
        });
        On<TeamMemberRemoved>(removed =>
        {
            if (!_isAssigned || removed.TenantId != _tenantId || removed.TeamId != _teamId ||
                removed.MemberId != _memberId || removed.MembershipEpisodeId != _membershipEpisodeId ||
                removed.AssignmentEventId != _assignmentEventId)
                throw new InvalidOperationException("Removal must close the exact team assignment and membership episode.");
            _isAssigned = false;
            _membershipEpisodeId = Uuid.Empty;
            _assignmentEventId = Uuid.Empty;
        });
    }

    public Result Assign(Uuid membershipEpisodeId = default)
    {
        if (_isAssigned && _membershipEpisodeId != membershipEpisodeId)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "Settle the prior membership assignment before assigning another episode."));
        if (!_isAssigned || _membershipEpisodeId != membershipEpisodeId)
            RaiseEvent(new TeamMemberAssigned(_tenantId, _teamId, _memberId, membershipEpisodeId));
        return Result.Success;
    }

    public Result Remove()
    {
        if (!_isAssigned)
            return Result.Failure(new RequestError(RequestErrorKind.NotFound, "The member is not on this team."));
        RaiseEvent(new TeamMemberRemoved(_tenantId, _teamId, _memberId, _membershipEpisodeId, _assignmentEventId));
        return Result.Success;
    }

    internal Result RemoveForRetirement(MembershipTerminationProof proof, Uuid assignmentEventId)
    {
        if (proof.TenantId != _tenantId || proof.MemberId != _memberId ||
            proof.MembershipEpisodeId == Uuid.Empty || proof.EventId == Uuid.Empty || assignmentEventId == Uuid.Empty)
            return Result.Failure(new RequestError(RequestErrorKind.Validation, "Exact retirement and assignment proofs are required."));
        if (Version == 0)
            return Result.Failure(new RequestError(RequestErrorKind.Conflict,
                "The proven team assignment is not available yet.", isTransient: true));
        if (!_isAssigned || _membershipEpisodeId != proof.MembershipEpisodeId || _assignmentEventId != assignmentEventId)
            return Result.Success;
        RaiseEvent(new TeamMemberRemoved(_tenantId, _teamId, _memberId, _membershipEpisodeId,
            _assignmentEventId, proof.EventId));
        return Result.Success;
    }
}

using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.AccessControl;

public sealed class TeamRole : Aggregate
{
    readonly Uuid _tenantId;
    readonly Uuid _teamId;
    readonly Uuid _roleId;
    readonly Uuid _selectedCommandId;
    DomainEvent? _selectedFact;
    Uuid? _assignmentId;

    public bool IsAssigned => _assignmentId is not null;
    public Uuid? AssignmentId => _assignmentId;
    public Uuid TenantId => _tenantId;
    public Uuid TeamId => _teamId;
    public Uuid RoleId => _roleId;

    public TeamRole(Uuid tenantId, Uuid teamId, Uuid roleId, Uuid selectedCommandId = default)
        : base(RbacIds.TeamRole(tenantId, teamId, roleId),
            new EventStreamAddress(tenantId.ToString(), "rbac-team-roles",
                RbacIds.TeamRole(tenantId, teamId, roleId).ToString()))
    {
        _tenantId = tenantId;
        _teamId = teamId;
        _roleId = roleId;
        _selectedCommandId = selectedCommandId;
        On<TeamRoleAssigned>(Apply);
        On<TeamRoleRemoved>(Apply);
    }

    public Result Assign(Uuid commandId, ulong expectedRevision, ActorAttribution actor)
    {
        if (Validate(commandId, actor) is { } error)
            return Result.Failure(error);
        if (_selectedFact is { } prior)
            return prior is TeamRoleAssigned assigned && assigned.ExpectedRevision == expectedRevision &&
                assigned.Actor == actor ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || IsAssigned)
            return Conflict("The team role changed or is already assigned.");
        RaiseEvent(new TeamRoleAssigned(_tenantId, _teamId, _roleId, commandId, expectedRevision, actor));
        return Result.Success;
    }

    public Result Remove(Uuid commandId, ulong expectedRevision, Uuid assignmentId, ActorAttribution actor)
    {
        if (Validate(commandId, actor) is { } error)
            return Result.Failure(error);
        if (assignmentId == Uuid.Empty)
            return Result.Failure(new RequestError(RequestErrorKind.Validation, "An assignment identity is required."));
        if (_selectedFact is { } prior)
            return prior is TeamRoleRemoved removed && removed.ExpectedRevision == expectedRevision &&
                removed.AssignmentId == assignmentId && removed.Actor == actor ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || _assignmentId != assignmentId)
            return Conflict("The team role revision or assignment episode changed.");
        RaiseEvent(new TeamRoleRemoved(_tenantId, _teamId, _roleId, commandId, expectedRevision, actor, assignmentId));
        return Result.Success;
    }

    RequestError? Validate(Uuid commandId, ActorAttribution actor) =>
        commandId == Uuid.Empty || commandId != _selectedCommandId || actor is null ||
        string.IsNullOrWhiteSpace(actor.Subject) || string.IsNullOrWhiteSpace(actor.Issuer)
            ? new RequestError(RequestErrorKind.Validation, "A selected command identity and original actor are required.")
            : null;

    void Apply(TeamRoleAssigned ev)
    {
        ValidateFact(ev.TenantId, ev.TeamId, ev.RoleId, ev.CommandId, ev.ExpectedRevision, ev.Actor, ev);
        if (IsAssigned)
            throw new InvalidOperationException("An active team role cannot be assigned again.");
        _assignmentId = ev.CommandId;
    }

    void Apply(TeamRoleRemoved ev)
    {
        ValidateFact(ev.TenantId, ev.TeamId, ev.RoleId, ev.CommandId, ev.ExpectedRevision, ev.Actor, ev);
        if (_assignmentId != ev.AssignmentId || ev.AssignmentId == Uuid.Empty)
            throw new InvalidOperationException("Team role removal must close the exact active assignment.");
        _assignmentId = null;
    }

    void ValidateFact(Uuid tenantId, Uuid teamId, Uuid roleId, Uuid commandId, ulong expectedRevision,
        ActorAttribution actor, DomainEvent fact)
    {
        if (tenantId != _tenantId || teamId != _teamId || roleId != _roleId || commandId == Uuid.Empty ||
            expectedRevision != Version || actor is null || string.IsNullOrWhiteSpace(actor.Subject) ||
            string.IsNullOrWhiteSpace(actor.Issuer))
            throw new InvalidOperationException("A team role fact must match its owner, actor and original revision.");
        if (commandId != _selectedCommandId)
            return;
        if (_selectedFact is not null)
            throw new InvalidOperationException("One team role operation cannot be accepted more than once.");
        _selectedFact = fact;
    }

    static Result ChangedIntent() => Conflict("This team role command identity already has different accepted intent.");
    static Result Conflict(string message) => Result.Failure(new RequestError(RequestErrorKind.Conflict, message));
}

using System.Globalization;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.Tenants;

/// <summary>One atomic active roster preserves the last-operator invariant.</summary>
public sealed class PlatformOperatorRoster : Aggregate
{
    static readonly Uuid RosterId = Uuid.Parse(
        "bc279ad5-e9ae-5033-a174-4d1350ce2b07", CultureInfo.InvariantCulture);
    readonly Dictionary<Uuid, Uuid> _operators = [];
    readonly Uuid _selectedCommandId;
    DomainEvent? _selectedFact;
    bool _initialized;

    public PlatformOperatorRoster(Uuid selectedCommandId = default)
        : base(RosterId, new EventStreamAddress("bdgrz", "platform-operator-roster", RosterId.ToString()))
    {
        _selectedCommandId = selectedCommandId;
        On<PlatformOperatorRosterSeeded>(Apply);
        On<PlatformOperatorGranted>(Apply);
        On<PlatformOperatorRevoked>(Apply);
    }

    public static Uuid CreationId => RosterId;
    public bool IsInitialized => _initialized;
    public bool HasSelectedOperation => _selectedFact is not null;
    public bool IsOperator(Uuid userId) => userId != Uuid.Empty && _operators.ContainsKey(userId);
    public Uuid? AssignmentId(Uuid userId) => _operators.TryGetValue(userId, out var id) ? id : null;
    public IReadOnlyList<PlatformOperatorAssignmentView> Operators => _operators
        .OrderBy(static entry => entry.Key.ToString(), StringComparer.Ordinal)
        .Select(static entry => new PlatformOperatorAssignmentView(entry.Key, entry.Value)).ToArray();

    public Result Seed(Uuid rosterId, IEnumerable<Uuid> configuredUserIds, ActorAttribution actor,
        DateTimeOffset occurredAt)
    {
        if (rosterId != RosterId || rosterId != _selectedCommandId || !ValidActor(actor))
            return Failure(RequestErrorKind.Validation, "The fixed roster creation identity and original actor are required.");
        var userIds = CanonicalUsers(configuredUserIds);
        if (userIds.Length == 0 || userIds.Contains(Uuid.Empty))
            return Failure(RequestErrorKind.Validation, "At least one valid bootstrap operator is required.");
        if (_selectedFact is { } prior)
            return prior is PlatformOperatorRosterSeeded seeded && seeded.Actor == actor &&
                seeded.UserIds.SequenceEqual(userIds) ? Result.Success : ChangedIntent();
        if (_initialized || Version != 0)
            return ChangedIntent();
        RaiseEvent(new PlatformOperatorRosterSeeded(rosterId, userIds, actor, occurredAt));
        return Result.Success;
    }

    public Result Grant(Uuid commandId, ulong expectedRevision, Uuid actorUserId, Uuid subjectUserId,
        string reason, ActorAttribution actor, DateTimeOffset occurredAt, string? actorDisplay = null)
    {
        if (ValidateChange(commandId, actorUserId, subjectUserId, reason, actor) is { } error)
            return Result.Failure(error);
        var canonicalReason = reason.Trim();
        if (_selectedFact is { } prior)
            return prior is PlatformOperatorGranted granted && granted.ExpectedRevision == expectedRevision &&
                granted.ActorUserId == actorUserId && granted.SubjectUserId == subjectUserId &&
                granted.Reason == canonicalReason && granted.Actor == actor ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || _operators.ContainsKey(subjectUserId))
            return Failure(RequestErrorKind.Conflict, "The operator roster changed or the user is already assigned.");
        RaiseEvent(new PlatformOperatorGranted(commandId, expectedRevision, actorUserId, subjectUserId,
            actor, occurredAt, canonicalReason, Display(actorUserId, actorDisplay)));
        return Result.Success;
    }

    public Result Revoke(Uuid commandId, ulong expectedRevision, Uuid actorUserId, Uuid subjectUserId,
        Uuid assignmentId, string reason, ActorAttribution actor, DateTimeOffset occurredAt, string? actorDisplay = null)
    {
        if (ValidateChange(commandId, actorUserId, subjectUserId, reason, actor) is { } error)
            return Result.Failure(error);
        if (assignmentId == Uuid.Empty)
            return Failure(RequestErrorKind.Validation, "An operator assignment identity is required.");
        var canonicalReason = reason.Trim();
        if (_selectedFact is { } prior)
            return prior is PlatformOperatorRevoked revoked && revoked.ExpectedRevision == expectedRevision &&
                revoked.ActorUserId == actorUserId && revoked.SubjectUserId == subjectUserId &&
                revoked.AssignmentId == assignmentId && revoked.Reason == canonicalReason && revoked.Actor == actor
                ? Result.Success : ChangedIntent();
        if (Version != expectedRevision || AssignmentId(subjectUserId) != assignmentId)
            return Failure(RequestErrorKind.Conflict, "The operator roster revision or assignment episode changed.");
        if (_operators.Count == 1)
            return Failure(RequestErrorKind.Conflict, "The last platform operator cannot be revoked.");
        RaiseEvent(new PlatformOperatorRevoked(commandId, expectedRevision, actorUserId, subjectUserId,
            assignmentId, actor, occurredAt, canonicalReason, Display(actorUserId, actorDisplay)));
        return Result.Success;
    }

    RequestError? ValidateChange(Uuid commandId, Uuid actorUserId, Uuid subjectUserId, string reason,
        ActorAttribution actor)
    {
        if (!_initialized || !IsOperator(actorUserId))
            return new RequestError(RequestErrorKind.Forbidden, "The actor is not a platform operator.");
        if (commandId == Uuid.Empty || commandId != _selectedCommandId || !ValidActor(actor))
            return new RequestError(RequestErrorKind.Validation, "A selected command identity and original actor are required.");
        if (subjectUserId == Uuid.Empty)
            return new RequestError(RequestErrorKind.Validation, "A platform user is required.");
        return ValidReason(reason) ? null :
            new RequestError(RequestErrorKind.Validation, "A reason of at most 500 characters is required.");
    }

    void Apply(PlatformOperatorRosterSeeded seeded)
    {
        if (_initialized || Version != 0 || seeded.RosterId != RosterId || !ValidActor(seeded.Actor) ||
            seeded.UserIds.Length == 0 || seeded.UserIds.Contains(Uuid.Empty) ||
            !seeded.UserIds.SequenceEqual(CanonicalUsers(seeded.UserIds)))
            throw new InvalidOperationException("The platform operator roster seed is invalid.");
        Select(seeded.RosterId, seeded);
        _initialized = true;
        foreach (var userId in seeded.UserIds)
            _operators.Add(userId, Uuid.CreateVersion5(RosterId, $"platform-operator:initial:{userId}"));
    }

    void Apply(PlatformOperatorGranted granted)
    {
        ValidateFact(granted.CommandId, granted.ExpectedRevision, granted.ActorUserId, granted.SubjectUserId,
            granted.Reason, granted.Actor);
        if (_operators.ContainsKey(granted.SubjectUserId))
            throw new InvalidOperationException("An active operator cannot be granted another assignment.");
        Select(granted.CommandId, granted);
        _operators.Add(granted.SubjectUserId, granted.CommandId);
    }

    void Apply(PlatformOperatorRevoked revoked)
    {
        ValidateFact(revoked.CommandId, revoked.ExpectedRevision, revoked.ActorUserId, revoked.SubjectUserId,
            revoked.Reason, revoked.Actor);
        if (revoked.AssignmentId == Uuid.Empty || AssignmentId(revoked.SubjectUserId) != revoked.AssignmentId ||
            _operators.Count == 1)
            throw new InvalidOperationException("Operator revocation must close the exact assignment and retain an operator.");
        Select(revoked.CommandId, revoked);
        _operators.Remove(revoked.SubjectUserId);
    }

    void ValidateFact(Uuid commandId, ulong expectedRevision, Uuid actorUserId, Uuid subjectUserId,
        string reason, ActorAttribution actor)
    {
        if (!_initialized || commandId == Uuid.Empty || expectedRevision != Version || !IsOperator(actorUserId) ||
            subjectUserId == Uuid.Empty || !ValidReason(reason) || reason != reason.Trim() || !ValidActor(actor))
            throw new InvalidOperationException("An operator fact must retain its actor, subject, reason and original revision.");
    }

    void Select(Uuid commandId, DomainEvent fact)
    {
        if (commandId != _selectedCommandId)
            return;
        if (_selectedFact is not null)
            throw new InvalidOperationException("One operator operation cannot be accepted twice.");
        _selectedFact = fact;
    }

    static bool ValidActor(ActorAttribution actor) => actor is not null &&
        !string.IsNullOrWhiteSpace(actor.Subject) && !string.IsNullOrWhiteSpace(actor.Issuer);
    static bool ValidReason(string reason) => !string.IsNullOrWhiteSpace(reason) && reason.Trim().Length <= 500;
    static Uuid[] CanonicalUsers(IEnumerable<Uuid> users) => users.Distinct()
        .OrderBy(static id => id.ToString(), StringComparer.Ordinal).ToArray();
    static string Display(Uuid userId, string? display) => string.IsNullOrWhiteSpace(display) ? userId.ToString() : display.Trim();
    static Result ChangedIntent() => Failure(RequestErrorKind.Conflict, "This operator operation already has different accepted intent.");
    static Result Failure(RequestErrorKind kind, string message) => Result.Failure(new RequestError(kind, message));
}

using System.Globalization;
using System.Security.Cryptography;
using System.Text.Json;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.UserIdentities;

/// <summary>An external identity provider association for a platform user.</summary>
public sealed class UserIdentity : Aggregate
{
    static Uuid IdentityNamespaceId { get; } =
        Uuid.Parse("17729a2d-d41d-5c56-953a-d3fe810cc8d2", CultureInfo.InvariantCulture);

    string? _provider;
    string? _identifier;
    bool _isRegistered;
    bool _isRevoked;
    Uuid _userId;
    Uuid _replacementIdentityId;
    string? _emailAddress;
    IdentityRegistrationProof? _registrationProof;

    public UserIdentity(string provider, string identifier)
        : this(CreateIdentityId(provider, identifier), provider, identifier)
    {
    }

    /// <summary>Hydrates an identity from its stable identity ID, for session revocation checks.</summary>
    public UserIdentity(Uuid identityId)
        : this(identityId, null, null)
    {
    }

    UserIdentity(Uuid identityId, string? provider, string? identifier)
        : base(identityId, new EventStreamAddress("bdgrz", "user-identities", identityId.ToString()))
    {
        _provider = provider;
        _identifier = identifier;
        On<UserIdentityRegistered>(Apply);
        On<UserIdentityRevoked>(Apply);
    }

    static Uuid CreateIdentityId(string provider, string identifier) =>
        Uuid.CreateVersion5(IdentityNamespaceId, $"{provider}\n{identifier}");

    public static Uuid GetIdentityId(string provider, string identifier)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(provider);
        ArgumentException.ThrowIfNullOrWhiteSpace(identifier);
        return CreateIdentityId(provider, identifier);
    }

    public bool IsRegistered => _isRegistered;

    public bool IsRevoked => _isRevoked;

    public Uuid UserId => _userId;

    public Result<AuthenticatedUserIdentity> Register(
        Uuid? userId,
        string? emailAddress)
    {
        if (_provider is null || _identifier is null)
        {
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(
                RequestErrorKind.Validation,
                "An identity must be registered from its provider and subject."));
        }

        if (userId == Uuid.Empty)
        {
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(
                RequestErrorKind.Validation,
                "A user identity requires a user ID."));
        }

        if (_isRegistered)
        {
            return userId is not null && _userId != userId.Value
                ? Result<AuthenticatedUserIdentity>.Failure(new RequestError(
                    RequestErrorKind.Conflict,
                    "The provider identity belongs to another user."))
                : Registered();
        }

        var registeredUserId = userId ?? Uuid.CreateVersion4();
        RaiseEvent(new UserIdentityRegistered(
            registeredUserId,
            _provider,
            _identifier,
            emailAddress));
        return Registered();
    }

    public Result<AuthenticatedUserIdentity> Authenticate()
    {
        if (_isRevoked)
        {
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(
                RequestErrorKind.Unauthorized,
                "The provider identity has been revoked."));
        }

        if (!_isRegistered || _provider is null || _identifier is null)
        {
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(
                RequestErrorKind.NotFound,
                "The user identity is not registered."));
        }

        AuditEvent(new UserIdentityAuthenticated(_userId, _provider, _identifier));
        return Result<AuthenticatedUserIdentity>.Success(
            new AuthenticatedUserIdentity(Id, _userId, _emailAddress));
    }

    public Result Revoke(Uuid replacementIdentityId, DateTimeOffset revokedAt)
    {
        if (!_isRegistered)
        {
            return Result.Failure(new RequestError(
                RequestErrorKind.NotFound,
                "The provider identity is not registered."));
        }

        if (replacementIdentityId == Uuid.Empty || replacementIdentityId == Id)
        {
            return Result.Failure(new RequestError(
                RequestErrorKind.Validation,
                "A provider identity must be replaced by a different registered identity."));
        }

        if (_isRevoked)
        {
            return _replacementIdentityId == replacementIdentityId
                ? Result.Success
                : Result.Failure(new RequestError(
                    RequestErrorKind.Conflict,
                    "The provider identity has already been replaced."));
        }

        RaiseEvent(new UserIdentityRevoked(Id, _userId, replacementIdentityId, revokedAt));
        return Result.Success;
    }

    public Result<AuthenticatedUserIdentity> ObserveAuthenticatedProfile(string? displayName,
        DateTimeOffset observedAt)
    {
        if (_isRevoked)
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(RequestErrorKind.Unauthorized,
                "The provider identity has been revoked."));
        if (!_isRegistered)
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(RequestErrorKind.NotFound,
                "The user identity is not registered."));
        if (observedAt == default)
            return Result<AuthenticatedUserIdentity>.Failure(new RequestError(RequestErrorKind.Validation,
                "A profile observation time is required."));
        var normalized = displayName?.Trim();
        if (string.IsNullOrEmpty(normalized) || normalized.Length > 200 || normalized.Any(char.IsControl))
            normalized = null;
        // Admission linearizes at this authoritative read. A later revocation does not invalidate
        // this historical observation, and this audit can never restore identity authority.
        AuditEvent(new UserIdentityProfileObserved(_userId, normalized, observedAt,
            _registrationProof ?? throw new InvalidOperationException("Registration provenance is required.")));
        return Registered();
    }

    void Apply(UserIdentityRegistered registered)
    {
        if (_isRegistered || registered.UserId == Uuid.Empty || registered.Metadata.AggregateVersion != 1 ||
            (_provider is not null && !string.Equals(registered.Provider, _provider, StringComparison.Ordinal)) ||
            (_identifier is not null && !string.Equals(registered.Identifier, _identifier, StringComparison.Ordinal)) ||
            CreateIdentityId(registered.Provider, registered.Identifier) != Id)
        {
            throw new InvalidOperationException("The user identity stream does not match its provider identity.");
        }

        _isRegistered = true;
        _provider = registered.Provider;
        _identifier = registered.Identifier;
        _userId = registered.UserId;
        _emailAddress = registered.EmailAddress;
        _registrationProof = new IdentityRegistrationProof(Id, registered.Metadata.EventId,
            registered.Metadata.AggregateVersion, registered.Metadata.AggregateVersion - 1,
            Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(registered,
                ComplianceCoreJsonContext.Default.UserIdentityRegistered))));
    }

    void Apply(UserIdentityRevoked revoked)
    {
        if (!_isRegistered || _isRevoked || revoked.UserIdentityId != Id || revoked.UserId != _userId ||
            revoked.ReplacementIdentityId == Id)
        {
            throw new InvalidOperationException("The identity revocation does not match its registered identity.");
        }

        _isRevoked = true;
        _replacementIdentityId = revoked.ReplacementIdentityId;
    }

    Result<AuthenticatedUserIdentity> Registered() =>
        Result<AuthenticatedUserIdentity>.Success(new AuthenticatedUserIdentity(Id, _userId, _emailAddress));
}
